using FluentAssertions; using Xunit;
namespace Sigov.ApiTests; public sealed class AgroParte5ApiTests{private static readonly string Infra=File.ReadAllText(Path.Combine(FindRepositoryRoot(),"src","Sigov.Api","Controllers","AgroInfraestruturaRuralController.cs")); private static readonly string Feiras=File.ReadAllText(Path.Combine(FindRepositoryRoot(),"src","Sigov.Api","Controllers","AgroFeirasController.cs")); private static readonly string Agroind=File.ReadAllText(Path.Combine(FindRepositoryRoot(),"src","Sigov.Api","Controllers","AgroAgroindustriasController.cs")); private static readonly string Compras=File.ReadAllText(Path.Combine(FindRepositoryRoot(),"src","Sigov.Api","Controllers","AgroComprasAgriculturaFamiliarController.cs")); [Fact] public void Controllers_exigem_login_e_modulo_agro(){Infra.Should().Contain("Authorize").And.Contain("RequireModule(\"agro\")"); Feiras.Should().Contain("Authorize").And.Contain("RequireModule(\"agro\")");} [Fact] public void Rotas_rest_parte_5_estao_presentes(){Infra.Should().Contain("api/agro/estradas-vicinais").And.Contain("api/agro/pontos-criticos/{id:long}/resolver").And.Contain("api/agro/manutencoes-rurais/{id:long}/executar"); Feiras.Should().Contain("api/agro/feiras").And.Contain("api/agro/feirantes/{id:long}/autorizar"); Agroind.Should().Contain("api/agro/agroindustrias").And.Contain("api/agro/inspecoes/{id:long}/concluir"); Compras.Should().Contain("api/agro/compras-agricultura-familiar/{id:long}/cancelar");} [Fact] public void Erros_de_acesso_sao_mapeados(){Infra.Should().Contain("Unauthorized").And.Contain("Forbid").And.Contain("UnprocessableEntity");} static string FindRepositoryRoot(){var d=new DirectoryInfo(AppContext.BaseDirectory); while(d is not null&&!File.Exists(Path.Combine(d.FullName,"sigov.sln")))d=d.Parent; return d?.FullName??throw new InvalidOperationException("Raiz do repositório não encontrada.");}}
